        const li = x - 1 - lo, ci = x - lo, ri = x + 1 - lo;
        next[ci] = R(cur[li], cur[ci], cur[ri]);
      }
      cur = next;
      const want2 = (t + phase) % 2;
      if (cur[0 - lo] !== want2) return { ok: false, depth };
      depth++;
