    row0.length = 0;
    for (let i = 0; i < nLeft; i++) row0.push((m >> i) & 1);
    row0.push(phase % 2); // x = 0
    // depth-first extension to the right
    const stack = [0];
    const rec = (k) => {
      const res = check(k);
      if (!res.ok) return;
      if (k + 1 > best) best = k + 1; // alternation verified for rows 0..k
      if (k + 1 >= cap) return;
      for (const b of [0, 1]) { row0.push(b); rec(k + 1); row0.pop(); }
